import sys
d={}
for l in sys.stdin:
    l=l.rstrip('\n')
    if '=' not in l: continue
    k,v=l.split('=',1)
    d[k]=v
for k in sorted(d): print(k,'->',d[k])

import sys
c={k:0 for k in ['ERROR','WARN','INFO','DEBUG']}
for l in sys.stdin:
    p=l.split(None,1)
    if p and p[0] in c: c[p[0]]+=1
for k in c: print(f'{k}: {c[k]}')

import sys
d={}
for l in sys.stdin:
    l=l.rstrip('\n')
    if l not in d: d[l]=len(d)
    print(d[l])

import sys
v={tuple(map(int,l.strip().split('.'))) for l in sys.stdin if l.strip()}
for t in sorted(v): print('.'.join(map(str,t)))

import sys
from collections import Counter
c=Counter()
for l in sys.stdin:
    if ':' in l: c[l.split(':',1)[0].strip()]+=1
for k,v in sorted(c.items(),key=lambda x:(-x[1],x[0])): print(k,v)

import re,sys
for l in sys.stdin:
    for m in re.findall(r'#(\d+)',l): print(m)
